"""MCP server generated by intpot."""


from pathlib import Path

from pydantic import Field as _intpot_mcp_field
from fastmcp import FastMCP as _intpot_mcp_fastmcp

UNIT_PRICE = 25

def quote_total(quantity: int, discount: int) -> int:
    subtotal = quantity * UNIT_PRICE
    if discount > subtotal:
        raise ValueError('discount exceeds subtotal')
    return subtotal - discount

mcp = _intpot_mcp_fastmcp('batch_quote')
_intpot_required = object()


def _quote_impl(
    quantity: int = _intpot_required,
    discount: int = 0,
    receipt: str = '',
) -> str:
    """Quote a bounded batch, optionally writing a receipt after validation."""
    if quantity is _intpot_required:
        raise TypeError('Missing required argument: quantity')
    total = quote_total(quantity, discount)
    if receipt:
        Path(receipt).write_text(str(total), encoding='utf-8')
    import builtins as _intpot_echo_builtins
    _intpot_echo_value = total
    return '' if _intpot_echo_value is None else _intpot_echo_builtins.str(_intpot_echo_value)


@mcp.tool(name='quote')
def quote(
    quantity: int = _intpot_mcp_field(..., ge=1, le=10),
    discount: int = _intpot_mcp_field(0, ge=0),
    receipt: str = '',
) -> str:
    """Quote a bounded batch, optionally writing a receipt after validation."""

    return _quote_impl(quantity, discount, receipt)


if __name__ == "__main__":
    mcp.run()
